import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { FiArrowRight, FiStar, FiBriefcase, FiUsers, FiCheck, FiTrendingUp, FiShield, FiAward, FiZap, FiClock, FiChevronLeft, FiChevronRight } from 'react-icons/fi';

const Home = () => {
  const [currentTestimonial, setCurrentTestimonial] = useState(0);
  const [stats, setStats] = useState({ students: 0, projects: 0, success: 0, clients: 0 });

  // Animated Counter
  useEffect(() => {
    const targets = { students: 5247, projects: 1893, success: 95, clients: 428 };
    const duration = 2000;
    const steps = 50;
    const increment = {
      students: targets.students / steps,
      projects: targets.projects / steps,
      success: targets.success / steps,
      clients: targets.clients / steps
    };
    
    let current = 0;
    const timer = setInterval(() => {
      current++;
      setStats({
        students: Math.min(Math.floor(increment.students * current), targets.students),
        projects: Math.min(Math.floor(increment.projects * current), targets.projects),
        success: Math.min(Math.floor(increment.success * current), targets.success),
        clients: Math.min(Math.floor(increment.clients * current), targets.clients)
      });
      if (current >= steps) clearInterval(timer);
    }, duration / steps);
    
    return () => clearInterval(timer);
  }, []);

  // Auto-rotate testimonials
  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTestimonial(prev => (prev + 1) % testimonials.length);
    }, 5000);
    return () => clearInterval(timer);
  }, []);

  const features = [
    { icon: <FiStar size={28}/>, title: 'AI-Powered Matching', desc: 'Smart algorithm matches students with projects for 95% success rate.', color: 'from-yellow-500 to-orange-600' },
    { icon: <FiShield size={28}/>, title: 'Secure Payments', desc: 'Payment protection with escrow. Money safe until completion.', color: 'from-green-500 to-emerald-600' },
    { icon: <FiZap size={28}/>, title: 'Instant Notifications', desc: 'Real-time updates on applications and project milestones.', color: 'from-blue-500 to-indigo-600' },
    { icon: <FiAward size={28}/>, title: 'Verified Profiles', desc: 'All users verified. Build trust with proven track records.', color: 'from-purple-500 to-pink-600' },
  ];

  const testimonials = [
    { name: 'Sarah Mitchell', role: 'Computer Science Student', avatar: 'SM', rating: 5, text: 'I landed my first freelance project within a week! Made $2,500 in my first month!', projects: 12 },
    { name: 'James Rodriguez', role: 'Design Student', avatar: 'JR', rating: 5, text: 'StudentHub connected me with amazing projects that match my skills perfectly!', projects: 8 },
    { name: 'Emily Chen', role: 'Marketing Student', avatar: 'EC', rating: 5, text: 'Professional platform. Clients are serious and payments on time. Highly recommend!', projects: 15 },
    { name: 'Michael Kumar', role: 'Web Dev Student', avatar: 'MK', rating: 5, text: 'From zero to 10 completed projects! StudentHub gave me real portfolio.', projects: 10 }
  ];

  const companies = ['TechCorp', 'StartupHub', 'DesignLab', 'CodeAcademy', 'DigitalPro', 'InnovateCo'];

  return (
    <div className="overflow-x-hidden">
      
      {/* HERO SECTION - FIXED VISIBILITY */}
      <section className="relative bg-gradient-to-br from-slate-900 via-green-900 to-slate-900 text-white py-20 lg:py-28">
        {/* Animated Background */}
        <div className="absolute inset-0 opacity-30">
          <div className="absolute top-20 left-10 w-96 h-96 bg-green-400 rounded-full blur-3xl animate-float"></div>
          <div className="absolute bottom-20 right-10 w-80 h-80 bg-blue-400 rounded-full blur-3xl animate-float" style={{animationDelay: '2s'}}></div>
        </div>

        <div className="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 z-10">
          <div className="grid lg:grid-cols-2 gap-12 items-center">
            
            {/* Left Content - FIXED TEXT VISIBILITY */}
            <div className="text-left">
              <div className="inline-flex items-center space-x-2 px-4 py-2 bg-green-500 bg-opacity-20 backdrop-blur-sm rounded-full mb-6 border border-green-400">
                <FiTrendingUp className="text-green-300" size={18} />
                <span className="text-green-100 text-sm font-bold">Trusted by 5,000+ Students</span>
              </div>

              {/* HEADING - NOW FULLY VISIBLE */}
              <h1 className="text-5xl lg:text-7xl font-black leading-tight mb-6 text-white drop-shadow-2xl">
                Build Your Career<br/>
                <span className="text-green-400">One Project</span><br/>
                at a Time
              </h1>

              <p className="text-xl text-gray-200 mb-8 leading-relaxed max-w-xl font-medium">
                The #1 freelance marketplace designed exclusively for students. Get matched with perfect projects using AI.
              </p>

              <div className="flex flex-col sm:flex-row gap-4 mb-12">
                <Link to="/register" className="group px-8 py-4 bg-green-500 hover:bg-green-600 text-white rounded-xl font-bold text-lg transition-all shadow-2xl hover:shadow-green-500/50 hover:scale-105 transform flex items-center justify-center space-x-2">
                  <span>Get Started Free</span>
                  <FiArrowRight className="group-hover:translate-x-1 transition-transform" size={20}/>
                </Link>
                <Link to="/browse" className="px-8 py-4 border-2 border-white bg-white bg-opacity-10 backdrop-blur-sm text-white rounded-xl font-bold text-lg hover:bg-white hover:text-gray-900 transition-all flex items-center justify-center space-x-2">
                  <FiBriefcase size={20}/>
                  <span>Browse Projects</span>
                </Link>
              </div>

              {/* Trust Badges */}
              <div className="flex flex-wrap items-center gap-6 text-sm">
                <div className="flex items-center space-x-2 text-green-300">
                  <FiCheck size={20}/>
                  <span className="font-semibold">100% Free to Join</span>
                </div>
                <div className="flex items-center space-x-2 text-green-300">
                  <FiShield size={20}/>
                  <span className="font-semibold">Secure Payments</span>
                </div>
              </div>
            </div>

            {/* Right - Stats Cards - FIXED VISIBILITY */}
            <div className="grid grid-cols-2 gap-6">
              {[
                { label: 'Active Students', value: stats.students.toLocaleString(), icon: <FiUsers size={28}/>, gradient: 'from-blue-500 to-blue-700', shadow: 'shadow-blue-500/50' },
                { label: 'Projects Posted', value: stats.projects.toLocaleString(), icon: <FiBriefcase size={28}/>, gradient: 'from-green-500 to-green-700', shadow: 'shadow-green-500/50' },
                { label: 'Success Rate', value: `${stats.success}%`, icon: <FiAward size={28}/>, gradient: 'from-orange-500 to-orange-700', shadow: 'shadow-orange-500/50' },
                { label: 'Happy Clients', value: stats.clients.toLocaleString(), icon: <FiStar size={28}/>, gradient: 'from-purple-500 to-purple-700', shadow: 'shadow-purple-500/50' }
              ].map((stat, i) => (
                <div key={i} className={`bg-white rounded-2xl p-6 shadow-xl ${stat.shadow} hover:scale-105 transition-all duration-300 transform`}>
                  <div className={`w-14 h-14 bg-gradient-to-br ${stat.gradient} rounded-xl flex items-center justify-center mb-4 text-white shadow-lg`}>
                    {stat.icon}
                  </div>
                  <p className="text-4xl font-black text-gray-900 mb-1">{stat.value}</p>
                  <p className="text-gray-600 text-sm font-semibold">{stat.label}</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* AS SEEN ON */}
      <section className="bg-white py-12 border-b">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <p className="text-center text-gray-500 text-sm font-bold mb-8 uppercase tracking-wider">Trusted by students from</p>
          <div className="flex flex-wrap justify-center items-center gap-12">
            {companies.map((company, i) => (
              <div key={i} className="text-2xl font-black text-gray-700 hover:text-green-600 transition-colors cursor-default">
                {company}
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* FEATURES */}
      <section className="py-20 bg-gray-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-16">
            <span className="px-4 py-2 bg-green-100 text-green-700 rounded-full text-sm font-bold uppercase">Why StudentHub</span>
            <h2 className="text-5xl font-black text-gray-900 mt-6 mb-4">Everything You Need</h2>
            <p className="text-xl text-gray-600 max-w-2xl mx-auto">Built for students. Every feature helps you land projects faster.</p>
          </div>
          <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-8">
            {features.map((f, i) => (
              <div key={i} className="bg-white rounded-2xl p-8 hover:shadow-2xl transition-all duration-300 border-2 border-gray-100 hover:border-green-500 transform hover:-translate-y-2">
                <div className={`w-16 h-16 bg-gradient-to-br ${f.color} rounded-2xl flex items-center justify-center mb-6 text-white shadow-lg`}>
                  {f.icon}
                </div>
                <h3 className="text-xl font-black text-gray-900 mb-3">{f.title}</h3>
                <p className="text-gray-600 leading-relaxed">{f.desc}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* TESTIMONIALS */}
      <section className="py-20 bg-gradient-to-br from-green-600 to-green-800 text-white">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-16">
            <span className="px-4 py-2 bg-white bg-opacity-20 rounded-full text-sm font-bold uppercase">Success Stories</span>
            <h2 className="text-5xl font-black mt-6 mb-4">Students Love Us</h2>
          </div>

          <div className="bg-white bg-opacity-10 backdrop-blur-lg rounded-3xl p-10 border border-white border-opacity-20 shadow-2xl">
            <div className="flex items-start space-x-6">
              <div className="w-20 h-20 bg-gradient-to-br from-green-400 to-teal-500 rounded-2xl flex items-center justify-center text-white text-2xl font-black shadow-xl flex-shrink-0">
                {testimonials[currentTestimonial].avatar}
              </div>
              <div className="flex-1">
                <div className="flex space-x-1 mb-4">
                  {[...Array(5)].map((_, i) => <FiStar key={i} className="text-yellow-400 fill-current" size={20}/>)}
                </div>
                <p className="text-2xl font-semibold mb-6 leading-relaxed">{testimonials[currentTestimonial].text}</p>
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-lg font-black">{testimonials[currentTestimonial].name}</p>
                    <p className="text-green-200">{testimonials[currentTestimonial].role}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-3xl font-black">{testimonials[currentTestimonial].projects}</p>
                    <p className="text-green-200 text-sm">Projects</p>
                  </div>
                </div>
              </div>
            </div>

            {/* Navigation */}
            <div className="flex items-center justify-center space-x-4 mt-8">
              <button onClick={() => setCurrentTestimonial((currentTestimonial - 1 + testimonials.length) % testimonials.length)} className="p-3 bg-white bg-opacity-20 hover:bg-opacity-30 rounded-full">
                <FiChevronLeft size={24}/>
              </button>
              <div className="flex space-x-2">
                {testimonials.map((_, i) => (
                  <button key={i} onClick={() => setCurrentTestimonial(i)} className={`h-2 rounded-full transition-all ${i === currentTestimonial ? 'bg-white w-8' : 'bg-white bg-opacity-50 w-2'}`}></button>
                ))}
              </div>
              <button onClick={() => setCurrentTestimonial((currentTestimonial + 1) % testimonials.length)} className="p-3 bg-white bg-opacity-20 hover:bg-opacity-30 rounded-full">
                <FiChevronRight size={24}/>
              </button>
            </div>
          </div>
        </div>
      </section>

      {/* FINAL CTA */}
      <section className="bg-gray-900 py-20">
        <div className="max-w-4xl mx-auto px-4 text-center">
          <h2 className="text-5xl lg:text-6xl font-black text-white mb-6">Ready to Start?</h2>
          <p className="text-xl text-gray-300 mb-10">Join thousands of students building careers on StudentHub.</p>
          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <Link to="/register" className="px-10 py-5 bg-green-500 hover:bg-green-600 text-white rounded-xl font-black text-lg shadow-2xl hover:scale-105 transform transition-all">Create Free Account</Link>
            <Link to="/browse" className="px-10 py-5 border-2 border-white text-white rounded-xl font-black text-lg hover:bg-white hover:text-gray-900 transition-all">Browse Projects</Link>
          </div>
        </div>
      </section>
    </div>
  );
};

export default Home;
